//! Bundled images for materials, generated by the program (seamlessly
//! tileable).

use dmxcraft_core::venue::model::{Blob, Texture};
use image::{Rgb, RgbImage};

use crate::i18n::t;

const N: u32 = 512;

/// Integer hash → 0–1.
fn hash(x: i32, y: i32, seed: u32) -> f32 {
    let mut h = (x as u32).wrapping_mul(0x8da6_b343)
        ^ (y as u32).wrapping_mul(0xd816_3841)
        ^ seed.wrapping_mul(0xcb1a_b31f);
    h ^= h >> 13;
    h = h.wrapping_mul(0x5bd1_e995);
    h ^= h >> 15;
    (h & 0xffff) as f32 / 65535.0
}

/// Smooth noise with a period of `period` cells (tileable).
fn noise(x: f32, y: f32, period: i32, seed: u32) -> f32 {
    let (x0, y0) = (x.floor() as i32, y.floor() as i32);
    let (fx, fy) = (x - x0 as f32, y - y0 as f32);
    let s = |v: f32| v * v * (3.0 - 2.0 * v);
    let w = |a: i32| a.rem_euclid(period);
    let v = |a: i32, b: i32| hash(w(a), w(b), seed);
    let a = v(x0, y0) + (v(x0 + 1, y0) - v(x0, y0)) * s(fx);
    let b = v(x0, y0 + 1) + (v(x0 + 1, y0 + 1) - v(x0, y0 + 1)) * s(fx);
    a + (b - a) * s(fy)
}

/// Several octaves of noise, 0–1. `u`, `v` in 0–1 (one tile).
fn fbm(u: f32, v: f32, base: i32, seed: u32) -> f32 {
    let mut sum = 0.0;
    let mut amp = 0.5;
    let mut p = base;
    for k in 0..5 {
        sum += noise(u * p as f32, v * p as f32, p, seed + k) * amp;
        amp *= 0.5;
        p *= 2;
    }
    sum / 0.97
}

fn mix(a: [f32; 3], b: [f32; 3], t: f32) -> [f32; 3] {
    [
        a[0] + (b[0] - a[0]) * t,
        a[1] + (b[1] - a[1]) * t,
        a[2] + (b[2] - a[2]) * t,
    ]
}

fn render(f: impl Fn(f32, f32) -> [f32; 3]) -> RgbImage {
    RgbImage::from_fn(N, N, |x, y| {
        let c = f(x as f32 / N as f32, y as f32 / N as f32);
        Rgb(c.map(|v| (v.clamp(0.0, 1.0) * 255.0).round() as u8))
    })
}

fn wood(u: f32, v: f32) -> [f32; 3] {
    // five planks per tile, each with its own tone and staggered joints
    let planks = 5.0;
    let row = (v * planks).floor();
    let fv = v * planks - row;
    let shift = hash(row as i32, 3, 7);
    let fu = (u + shift).fract();
    let tone = hash(row as i32, 1, 11);
    let grain = fbm(fu * 0.25, fv * 4.0 + row, 4, 3);
    let lines = ((fv * 9.0 + grain * 6.0) * std::f32::consts::PI).sin() * 0.5 + 0.5;
    let c = mix(
        [0.42, 0.27, 0.15],
        [0.62, 0.42, 0.25],
        tone * 0.6 + lines * 0.4,
    );
    let joint = !(0.012..=0.988).contains(&fv)
        || ((fu * 2.0).fract() < 0.004 && hash(row as i32, 5, 1) > 0.5);
    if joint {
        mix(c, [0.1, 0.06, 0.03], 0.7)
    } else {
        c
    }
}

fn stage(u: f32, v: f32) -> [f32; 3] {
    let n = fbm(u, v, 8, 21);
    let planks = 8.0;
    let fv = (v * planks).fract();
    let base = 0.045 + n * 0.035;
    let c = [base, base, base * 1.05];
    if !(0.01..=0.99).contains(&fv) {
        [0.02, 0.02, 0.02]
    } else {
        c
    }
}

fn concrete(u: f32, v: f32) -> [f32; 3] {
    let n = fbm(u, v, 6, 31);
    let speck = if hash((u * 400.0) as i32, (v * 400.0) as i32, 9) > 0.985 {
        -0.12
    } else {
        0.0
    };
    let g = 0.48 + (n - 0.5) * 0.35 + speck;
    [g, g * 0.99, g * 0.97]
}

fn carpet(u: f32, v: f32) -> [f32; 3] {
    let n = fbm(u, v, 16, 41);
    let fine = hash((u * N as f32) as i32, (v * N as f32) as i32, 5);
    let t = n * 0.6 + fine * 0.4;
    mix([0.28, 0.05, 0.06], [0.45, 0.1, 0.1], t)
}

fn brick(u: f32, v: f32) -> [f32; 3] {
    // 4 rows × 2 bricks per tile, staggered
    let rows = 4.0;
    let r = (v * rows).floor();
    let fv = v * rows - r;
    let off = if r as i32 % 2 == 0 { 0.0 } else { 0.25 };
    let x = (u + off).fract() * 2.0;
    let col = x.floor();
    let fu = x - col;
    let mortar = !(0.04..=0.96).contains(&fv) || !(0.02..=0.98).contains(&fu);
    if mortar {
        let g = 0.62 + fbm(u, v, 16, 2) * 0.1;
        return [g, g * 0.97, g * 0.92];
    }
    let tone = hash(r as i32, col as i32 + if off > 0.0 { 9 } else { 0 }, 13);
    let n = fbm(u, v, 12, 17);
    mix([0.45, 0.17, 0.11], [0.62, 0.28, 0.18], tone * 0.6 + n * 0.4)
}

fn tiles(u: f32, v: f32) -> [f32; 3] {
    let n = 4.0;
    let (fu, fv) = ((u * n).fract(), (v * n).fract());
    if !(0.015..=0.985).contains(&fu) || !(0.015..=0.985).contains(&fv) {
        return [0.55, 0.55, 0.53];
    }
    let g = 0.86 + fbm(u, v, 8, 61) * 0.06;
    [g, g, g * 0.98]
}

fn molton(u: f32, v: f32) -> [f32; 3] {
    // black stage fabric with vertical folds
    let fold = ((u * 12.0 + fbm(u, v, 2, 71) * 1.5) * std::f32::consts::TAU).sin() * 0.5 + 0.5;
    let g = 0.025 + fold * 0.03 + hash((u * N as f32) as i32, (v * N as f32) as i32, 3) * 0.008;
    [g, g, g * 1.1]
}

fn light_wood(u: f32, v: f32) -> [f32; 3] {
    let c = wood(u, v);
    // brighter, slightly yellow oak
    [c[0] * 1.45 + 0.08, c[1] * 1.5 + 0.07, c[2] * 1.45 + 0.04]
}

fn parquet(u: f32, v: f32) -> [f32; 3] {
    // herringbone: 4 × 4 blocks of three staves each, alternating direction
    let n = 4.0;
    let (bx, by) = ((u * n).floor(), (v * n).floor());
    let (fu, fv) = ((u * n).fract(), (v * n).fract());
    let vertical = (bx + by) as i32 % 2 == 0;
    let (along, across) = if vertical { (fv, fu) } else { (fu, fv) };
    let stave = (across * 3.0).floor();
    let fa = (across * 3.0).fract();
    let tone = hash(bx as i32 * 7 + stave as i32, by as i32, 23);
    let grain = fbm(u * 2.0 + stave * 0.1, v * 2.0, 8, 29);
    let c = mix(
        [0.46, 0.29, 0.15],
        [0.66, 0.45, 0.26],
        tone * 0.7 + grain * 0.3,
    );
    if !(0.03..=0.97).contains(&fa) || !(0.01..=0.99).contains(&along) {
        mix(c, [0.12, 0.07, 0.04], 0.6)
    } else {
        c
    }
}

fn marble(u: f32, v: f32) -> [f32; 3] {
    let n = fbm(u, v, 4, 81);
    let veins = ((u + v + n * 2.5) * std::f32::consts::TAU * 2.0)
        .sin()
        .abs();
    let vein = (1.0 - veins).powf(10.0);
    let g = 0.88 - vein * 0.45 + (fbm(u, v, 16, 83) - 0.5) * 0.06;
    [g, g * 0.99, g * 0.97]
}

fn plaster(u: f32, v: f32) -> [f32; 3] {
    let n = fbm(u, v, 8, 91) - 0.5;
    let fine = hash((u * N as f32) as i32, (v * N as f32) as i32, 93) - 0.5;
    let g = 0.86 + n * 0.08 + fine * 0.025;
    [g, g * 0.985, g * 0.95]
}

fn stone_wall(u: f32, v: f32) -> [f32; 3] {
    // irregular stones: 3 rows, varying widths, grey-brown
    let rows = 3.0;
    let r = (v * rows).floor();
    let fv = v * rows - r;
    let off = hash(r as i32, 0, 101) * 0.5;
    let count = 3.0;
    let x = (u + off).fract() * count;
    let col = x.floor();
    let fu = x - col;
    let edge = fu.min(1.0 - fu).min(fv.min(1.0 - fv)) + (fbm(u, v, 16, 103) - 0.5) * 0.06;
    let tone = hash(r as i32, col as i32, 107);
    let n = fbm(u, v, 8, 109);
    let c = mix([0.34, 0.31, 0.28], [0.58, 0.54, 0.48], tone * 0.6 + n * 0.4);
    if edge < 0.05 {
        mix(c, [0.16, 0.15, 0.14], 0.8)
    } else {
        c
    }
}

fn velvet(u: f32, v: f32) -> [f32; 3] {
    // red stage curtain with soft vertical folds
    let fold = ((u * 10.0 + fbm(u, v, 2, 111) * 1.2) * std::f32::consts::TAU).sin() * 0.5 + 0.5;
    let g =
        0.35 + fold * 0.45 + (hash((u * N as f32) as i32, (v * N as f32) as i32, 113) - 0.5) * 0.04;
    [0.42 * g, 0.03 * g, 0.05 * g]
}

fn metal(u: f32, v: f32) -> [f32; 3] {
    // brushed metal: fine horizontal streaks
    let streak = fbm(u * 0.5, v * 64.0, 4, 121);
    let g = 0.56 + (streak - 0.5) * 0.18;
    [g, g * 1.01, g * 1.04]
}

fn checker(u: f32, v: f32) -> [f32; 3] {
    let n = 4.0;
    let dark = ((u * n).floor() as i32 + (v * n).floor() as i32) % 2 == 0;
    let g = if dark { 0.06 } else { 0.85 };
    let n = (fbm(u, v, 8, 131) - 0.5) * 0.04;
    [g + n, g + n, g + n]
}

fn paneling(u: f32, v: f32) -> [f32; 3] {
    // vertical wooden boards
    wood(v, u)
}

fn asphalt(u: f32, v: f32) -> [f32; 3] {
    let n = fbm(u, v, 8, 141);
    let grain = hash((u * N as f32) as i32, (v * N as f32) as i32, 143);
    let g = 0.13 + n * 0.06 + grain * 0.06;
    [g, g, g * 1.02]
}

fn cobblestone(u: f32, v: f32) -> [f32; 3] {
    // rounded stones in a grid of 6 × 6 cells, jittered
    let n = 6.0;
    let (cx, cy) = ((u * n).floor(), (v * n).floor());
    let (fu, fv) = ((u * n).fract() - 0.5, (v * n).fract() - 0.5);
    let d = (fu * fu + fv * fv).sqrt() + (fbm(u, v, 24, 151) - 0.5) * 0.15;
    let tone = hash(cx as i32, cy as i32, 153);
    if d > 0.46 {
        [0.18, 0.17, 0.15]
    } else {
        let shade = 1.0 - d * 0.6;
        let c = mix([0.38, 0.36, 0.33], [0.55, 0.52, 0.47], tone);
        [c[0] * shade, c[1] * shade, c[2] * shade]
    }
}

/// Generator of an image: (u, v) in 0–1 → color.
pub type Pattern = fn(f32, f32) -> [f32; 3];

/// Bundled images: name, recommended tile size (m), generator.
pub fn builtin() -> Vec<(&'static str, f32, Pattern)> {
    vec![
        (t("Wooden planks"), 2.0, wood),
        (t("Black stage floor"), 2.0, stage),
        (t("Concrete"), 2.0, concrete),
        (t("Carpet"), 1.0, carpet),
        (t("Brick"), 1.0, brick),
        (t("Tiles"), 1.2, tiles),
        (t("Molton"), 1.5, molton),
        (t("Light wood"), 2.0, light_wood),
        (t("Parquet"), 1.0, parquet),
        (t("Wood paneling"), 2.0, paneling),
        (t("Marble"), 1.5, marble),
        (t("Plaster"), 2.0, plaster),
        (t("Stone wall"), 1.5, stone_wall),
        (t("Cobblestone"), 1.0, cobblestone),
        (t("Asphalt"), 2.0, asphalt),
        (t("Checkered floor"), 2.0, checker),
        (t("Velvet curtain"), 1.5, velvet),
        (t("Brushed metal"), 1.0, metal),
    ]
}

/// Generate an image and save it as PNG.
pub fn make(name: &str, f: Pattern) -> Texture {
    let img = render(f);
    let mut png = Vec::new();
    img.write_to(&mut std::io::Cursor::new(&mut png), image::ImageFormat::Png)
        .expect("PNG into memory");
    Texture {
        name: name.to_string(),
        data: Blob(png.into()),
    }
}

/// Load an image file (PNG or JPEG, at most 16 MB).
pub fn load_file(path: &std::path::Path) -> Result<Texture, String> {
    let bytes = std::fs::read(path).map_err(|e| e.to_string())?;
    if bytes.len() > 16 * 1024 * 1024 {
        return Err(t("Image too large (16 MB max)").to_string());
    }
    match image::guess_format(&bytes) {
        Ok(image::ImageFormat::Png | image::ImageFormat::Jpeg) => {}
        _ => return Err(t("Only PNG or JPEG images").to_string()),
    }
    image::load_from_memory(&bytes).map_err(|e| e.to_string())?;
    Ok(Texture {
        name: path
            .file_stem()
            .map_or_else(|| "Image".into(), |s| s.to_string_lossy().into_owned()),
        data: Blob(bytes.into()),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn builtins_are_seamless_and_decode() {
        for (name, _, f) in builtin() {
            let tex = make(name, f);
            let img = image::load_from_memory(&tex.data.0).unwrap().to_rgb8();
            assert_eq!(img.dimensions(), (N, N));
            // The edges match (small difference, no seam)
            let diff = |a: &Rgb<u8>, b: &Rgb<u8>| {
                a.0.iter()
                    .zip(b.0)
                    .map(|(x, y)| (*x as i32 - y as i32).abs())
                    .max()
                    .unwrap()
            };
            // a checkerboard alternates at the edge by design
            if name == t("Checkered floor") {
                continue;
            }
            let mut worst = 0;
            for y in 0..N {
                worst = worst.max(diff(img.get_pixel(0, y), img.get_pixel(N - 1, y)));
            }
            assert!(worst < 90, "{name}: {worst}");
        }
    }
}
